     "html": "Probabilitatearen Teoriak Laplaceren eskutik izan zuen garrantzirik handiena. 50 urte baino gehiago igaro behar izan ziren bere ikuspuntuak gainditu ahal izateko. P.L. Chebychev errusiar matematikariak (1821-1894) A. Markov (1856-1922) eta A.M. Lyapunov (1857-1918) bere ikasleekin batera, oraindik ebatzi gabe zeuden problema asko ikertu eta ebatzi zituen. Bere lanek eragin handia izan zuten geroko matematikan, batez ere &quot;errusiar eskola&quot; izeneko joeran."
