       "html": "Tau neutrinoen esperimentua, bi detektagailu independente: <math display=\"inline\"><msub><mi>N</mi><mn>12</mn></msub></math> gertaera bietan, <math display=\"inline\"><mrow><msub><mi>N</mi><mn>12</mn></msub><mo>+</mo><msub><mi>N</mi><mn>1</mn></msub></mrow></math> lehenengoan, <math display=\"inline\"><mrow><msub><mi>N</mi><mn>12</mn></msub><mo>+</mo><msub><mi>N</mi><mn>2</mn></msub></mrow></math> bigarrenean, <math display=\"inline\"><mi>N</mi></math> guztira (ezezaguna). a) Eraginkortasunak <math display=\"inline\"><mrow><mi>P</mi><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>1</mn><mo stretchy=\"false\" form=\"postfix\">)</mo></mrow></math>, <math display=\"inline\"><mrow><mi>P</mi><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>2</mn><mo stretchy=\"false\" form=\"postfix\">)</mo></mrow></math>; b) bietan behatua izateko probabilitatea (bi eratara); d) berdinduz askatu <math display=\"inline\"><mi>N</mi></math>; e) bi neurketak konbinatuta, prozesuaren eraginkortasuna. (Eraginkortasun-kalibrazioaren teknika erreala.)"
