       "html": "Jonek lau aurpegiko bi dado botatzen ditu; Ruthek azpiko aurpegien batura <math display=\"inline\"><mi>x</mi></math> asmatu behar du: asmatuz gero <math display=\"inline\"><msup><mi>x</mi><mn>2</mn></msup></math> euro irabazi, bestela <math display=\"inline\"><mi>x</mi></math> ordaindu. Aztertu Ruthen irabazi esperoa hiru estrategiatan: a)  <math display=\"inline\"><mi>x</mi></math> zoriz <math display=\"inline\"><mrow><mo stretchy=\"false\" form=\"prefix\">[</mo><mn>2</mn><mo>,</mo><mn>8</mn><mo stretchy=\"false\" form=\"postfix\">]</mo></mrow></math>-n; b) bere bi dadoak botata ateratzen zaiona; d) beti zenbaki bera — zein gomendatuko zenioke?"
