       "mota": "testua",
       "html": "<math display=\"inline\"><mrow><mi>k</mi><mo>=</mo><mn>100</mn></mrow></math> probabilitate txikiko gertaera independente neurtuta: zein da <math display=\"inline\"><mi>σ</mi></math>? Zeintzuk dira %90eko konfiantza-mugak <math display=\"inline\"><mi>μ</mi></math>-ren inguruan? Eta <math display=\"inline\"><mrow><mi>k</mi><mo>=</mo><mn>1</mn></mrow></math> neurtu badugu: a) gertaera bat edo gutxiago neurtzeko probabilitatea (<math display=\"inline\"><mrow><mi>μ</mi><mo>=</mo><mn>1</mn></mrow></math> balitz); b) bat baino gehiago neurtzekoa; zeintzuk dira orduan konfiantza-mugak? (Poisson kontagailu-estatistikan.)"
