      "<math display=\"inline\"><mrow><mi>A</mi><mo>∪</mo><mi>B</mi></mrow></math> gertaera egiaztatzen da bietako bat (<math display=\"inline\"><mi>A</mi></math> edo <math display=\"inline\"><mi>B</mi></math>) edo biak gertatzen direnean.",
      "<math display=\"inline\"><mrow><mi>A</mi><mo>∩</mo><mi>B</mi></mrow></math> gertaera egiaztatzen da <math display=\"inline\"><mi>A</mi></math> eta <math display=\"inline\"><mi>B</mi></math> aldi berean gertatzen direnean.",
      "<math display=\"inline\"><mrow><mi>A</mi><mo>−</mo><mi>B</mi></mrow></math> egiaztatzen da <math display=\"inline\"><mi>A</mi></math> gertatzen eta <math display=\"inline\"><mi>B</mi></math> gertatzen ez denean.",
      "<math display=\"inline\"><msup><mi>A</mi><mo>′</mo></msup></math> gertaera, <math display=\"inline\"><mi>A</mi></math>-ren aurkakoa, <math display=\"inline\"><mi>A</mi></math> egiaztatzen ez denean egiaztatzen da.",
      "Gertaera bateraezinak ezin dira aldi berean egiaztatu."
