       "mota": "testua",
       "html": "Dado bat behin eta berriro botatzen dugunean, posible da &quot;3&quot; gertaera bost aldiz jarraian lortzea? Bai horixe! Zaila da, baina gerta daiteke. Nola eragiten dio bolada horrek <math display=\"inline\"><mrow><mi>f</mi><mi>r</mi><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>3</mn><mo stretchy=\"false\" form=\"postfix\">)</mo></mrow></math>-ri? Bada, zenbat esperientzia egin dugun arabera. Esaterako, pentsa dezagun bolada horren aurretik <math display=\"inline\"><mrow><mi>f</mi><mi>r</mi><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>3</mn><mo stretchy=\"false\" form=\"postfix\">)</mo><mo>=</mo><mn>0</mn><mo>,</mo><mn>16</mn></mrow></math> zela."
