         "html": "<math display=\"inline\"><mrow><mi>P</mi><mo stretchy=\"false\" form=\"prefix\">[</mo><mi>A</mi><mo>∪</mo><mi>B</mi><mo stretchy=\"false\" form=\"postfix\">]</mo><mo>=</mo><mi>P</mi><mo stretchy=\"false\" form=\"prefix\">[</mo><mi>A</mi><mo stretchy=\"false\" form=\"postfix\">]</mo><mo>+</mo><mi>P</mi><mo stretchy=\"false\" form=\"prefix\">[</mo><mi>B</mi><mo stretchy=\"false\" form=\"postfix\">]</mo><mo>−</mo><mi>P</mi><mo stretchy=\"false\" form=\"prefix\">[</mo><mi>A</mi><mo>∩</mo><mi>B</mi><mo stretchy=\"false\" form=\"postfix\">]</mo></mrow></math> dela egiaztatzeko argibideak"
