      {
       "mota": "testua",
       "html": "<em>b)</em>"
      },
      {
       "mota": "testua",
       "html": "Karta multzoa &quot;Laplaceren&quot; zorizko tresna da, karta horietako bakoitza ateratzeko probabilitatea berdina delako. Karta sorta horretan errege bastoa ateratzeko probabilitatea <math display=\"inline\"><mfrac><mn>1</mn><mn>20</mn></mfrac></math> bada, 20 karta daudelako da."
      }
