         "mota": "testua",
         "html": "<math display=\"block\"><mrow><mi>P</mi><mrow><mo stretchy=\"true\" form=\"prefix\">[</mo><msub><mi>S</mi><mn>1</mn></msub><mspace width=\"0.222em\"></mspace><mn>1</mn><mi>.</mi><mi>a</mi><mi>n</mi><mspace width=\"0.222em\"></mspace><mi>e</mi><mi>t</mi><mi>a</mi><mspace width=\"0.222em\"></mspace><msub><mi>S</mi><mn>2</mn></msub><mspace width=\"0.222em\"></mspace><mn>2</mn><mi>.</mi><mi>e</mi><mi>a</mi><mi>n</mi><mspace width=\"0.222em\"></mspace><mi>e</mi><mi>t</mi><mi>a</mi><mspace width=\"0.222em\"></mspace><msub><mi>S</mi><mn>3</mn></msub><mspace width=\"0.222em\"></mspace><mn>3</mn><mi>.</mi><mi>e</mi><mi>a</mi><mi>n</mi><mo stretchy=\"true\" form=\"postfix\">]</mo></mrow><mo>=</mo><mi>P</mi><mrow><mo stretchy=\"true\" form=\"prefix\">[</mo><msub><mi>S</mi><mn>1</mn></msub><mo stretchy=\"true\" form=\"postfix\">]</mo></mrow><mo>⋅</mo><mi>P</mi><mrow><mo stretchy=\"true\" form=\"prefix\">[</mo><msub><mi>S</mi><mn>2</mn></msub><mi>/</mi><msub><mi>S</mi><mn>1</mn></msub><mo stretchy=\"true\" form=\"postfix\">]</mo></mrow><mo>⋅</mo><mi>P</mi><mrow><mo stretchy=\"true\" form=\"prefix\">[</mo><msub><mi>S</mi><mn>3</mn></msub><mi>/</mi><msub><mi>S</mi><mn>1</mn></msub><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> eta </mtext><mspace width=\"0.333em\"></mspace></mrow><msub><mi>S</mi><mn>2</mn></msub><mo stretchy=\"true\" form=\"postfix\">]</mo></mrow></mrow></math>"
