       "html": "Dado bat eta goian aipatutako kutxa biak ditugu. Dadoa botatzen dugu. 1 edo 2 irteten bada ① kutxara joko dugu. 3, 4, 5 edo 6 irteten badira, ② kutxara joko dugu. Dadoa bota eta pilota dagokion kutxatik ateratzen dugu."
