       "mota": "testua",
       "html": "Esan <math display=\"inline\"><mrow><mi>P</mi><mrow><mo stretchy=\"true\" form=\"prefix\">[</mo><mrow><mo stretchy=\"true\" form=\"prefix\">{</mo><mn>3</mn><mo>,</mo><mn>4</mn><mo>,</mo><mn>5</mn><mo>,</mo><mn>6</mn><mo stretchy=\"true\" form=\"postfix\">}</mo></mrow><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> eta beltza</mtext></mrow><mo stretchy=\"true\" form=\"postfix\">]</mo></mrow></mrow></math>, <math display=\"inline\"><mrow><mi>P</mi><mrow><mo stretchy=\"true\" form=\"prefix\">[</mo><mtext mathvariant=\"normal\">zuria</mtext><mo stretchy=\"true\" form=\"postfix\">]</mo></mrow></mrow></math>, <math display=\"inline\"><mrow><mi>P</mi><mrow><mo stretchy=\"true\" form=\"prefix\">[</mo><mtext mathvariant=\"normal\">gorria</mtext><mo stretchy=\"true\" form=\"postfix\">]</mo></mrow></mrow></math>, <math display=\"inline\"><mrow><mi>P</mi><mrow><mo stretchy=\"true\" form=\"prefix\">[</mo><mtext mathvariant=\"normal\">beltza</mtext><mo stretchy=\"true\" form=\"postfix\">]</mo></mrow></mrow></math>-ren balioak."
