     "html": "Kontutan izanda <math display=\"inline\"><mrow><mi>P</mi><mrow><mo stretchy=\"true\" form=\"prefix\">[</mo><msub><mi>A</mi><mi>k</mi></msub><mo>∩</mo><mi>S</mi><mo stretchy=\"true\" form=\"postfix\">]</mo></mrow><mo>=</mo><mi>P</mi><mrow><mo stretchy=\"true\" form=\"prefix\">[</mo><msub><mi>A</mi><mi>k</mi></msub><mo stretchy=\"true\" form=\"postfix\">]</mo></mrow><mo>⋅</mo><mi>P</mi><mrow><mo stretchy=\"true\" form=\"prefix\">[</mo><mi>S</mi><mi>/</mi><msub><mi>A</mi><mi>k</mi></msub><mo stretchy=\"true\" form=\"postfix\">]</mo></mrow></mrow></math> dela, aurkitu nahi dugun adierazpena lortuko dugu."
