     "html": "Zuhaitz diagrama aztertuz gero, ikusten dugu zein zentzu duten kasu honetan <math display=\"inline\"><mrow><mi>P</mi><mrow><mo stretchy=\"true\" form=\"prefix\">[</mo><mi>S</mi><mi>/</mi><msub><mi>A</mi><mi>i</mi></msub><mo stretchy=\"true\" form=\"postfix\">]</mo></mrow></mrow></math>, <math display=\"inline\"><mrow><mi>P</mi><mrow><mo stretchy=\"true\" form=\"prefix\">[</mo><msub><mi>A</mi><mi>i</mi></msub><mo>∩</mo><mi>S</mi><mo stretchy=\"true\" form=\"postfix\">]</mo></mrow><mo>=</mo><mi>P</mi><mrow><mo stretchy=\"true\" form=\"prefix\">[</mo><msub><mi>A</mi><mi>i</mi></msub><mo stretchy=\"true\" form=\"postfix\">]</mo></mrow><mo>⋅</mo><mi>P</mi><mrow><mo stretchy=\"true\" form=\"prefix\">[</mo><mi>S</mi><mi>/</mi><msub><mi>A</mi><mi>i</mi></msub><mo stretchy=\"true\" form=\"postfix\">]</mo></mrow></mrow></math> eta <math display=\"inline\"><mrow><mi>P</mi><mo stretchy=\"false\" form=\"prefix\">[</mo><mi>S</mi><mo stretchy=\"false\" form=\"postfix\">]</mo></mrow></math> probabilitateek probabilitate oso gisa. Argi dago prozesu hori kasu hauetarako oso baliagarria dela, <math display=\"inline\"><mi>S</mi></math>-ra <math display=\"inline\"><mrow><msub><mi>A</mi><mn>1</mn></msub><mo>,</mo><msub><mi>A</mi><mn>2</mn></msub><mo>,</mo><mi>…</mi><mo>,</mo><msub><mi>A</mi><mi>n</mi></msub></mrow></math>-tik igaroz bakarrik heldu daiteke-eta."
