         "mota": "testua",
         "html": "<math display=\"inline\"><mi>A</mi></math> kutxan 5 bola zuri eta 3 beltz daude. <math display=\"inline\"><mi>B</mi></math> kutxan 6 bola zuri eta 4 beltz. Kutxa bat hartu, zorian, eta bi bola ateratzen ditugu: biak beltzak izan dira. Aurkitu zein probabilitate dagoen hartu duguna <math display=\"inline\"><mi>B</mi></math> kutxa izan dadin."
