         "html": "<math display=\"inline\"><mi>A</mi></math>, <math display=\"inline\"><mi>B</mi></math> eta <math display=\"inline\"><mi>C</mi></math> ondokoa betetzen duten hiru gertaera dira: <math display=\"inline\"><mi>A</mi></math> eta <math display=\"inline\"><mi>B</mi></math> disjuntuak dira, <math display=\"inline\"><mi>A</mi></math> eta <math display=\"inline\"><mi>C</mi></math> askeak dira eta <math display=\"inline\"><mi>B</mi></math> eta <math display=\"inline\"><mi>C</mi></math> ere askeak dira. Badakigu <math display=\"inline\"><mrow><mi>P</mi><mo stretchy=\"false\" form=\"prefix\">(</mo><mi>A</mi><mo stretchy=\"false\" form=\"postfix\">)</mo><mo>=</mo><mfrac><mn>1</mn><mn>3</mn></mfrac></mrow></math>, <math display=\"inline\"><mrow><mi>P</mi><mo stretchy=\"false\" form=\"prefix\">(</mo><mi>B</mi><mo stretchy=\"false\" form=\"postfix\">)</mo><mo>=</mo><mfrac><mn>1</mn><mn>4</mn></mfrac></mrow></math> eta <math display=\"inline\"><mrow><mi>P</mi><mo stretchy=\"false\" form=\"prefix\">(</mo><mi>C</mi><mo stretchy=\"false\" form=\"postfix\">)</mo><mo>=</mo><mfrac><mn>1</mn><mn>6</mn></mfrac></mrow></math> direla. Kalkulatu:"
