       "html": "<math display=\"inline\"><mi>A</mi></math>, <math display=\"inline\"><mi>B</mi></math> eta <math display=\"inline\"><mi>C</mi></math> zorizko esperientzia bateko hautazko gertaerak dira. Adierazi &quot;<math display=\"inline\"><mi>A</mi></math>, <math display=\"inline\"><mi>B</mi></math> eta <math display=\"inline\"><mi>C</mi></math>-tik bi gertaera zehatz gertatzen dira&quot; gertaera."
