       "html": "<math display=\"block\"><mrow><mi>W</mi><mo>=</mo><munderover><mo>∏</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>R</mi></munderover><mfrac><mrow><msub><mi>g</mi><mi>i</mi></msub><mi>!</mi></mrow><mrow><msub><mi>n</mi><mrow><mi>i</mi><mi>!</mi></mrow></msub><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><msub><mi>g</mi><mi>i</mi></msub><mo>−</mo><msub><mi>n</mi><mi>i</mi></msub><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mi>!</mi></mrow></mfrac><mspace width=\"1.0em\"></mspace><mo>⇒</mo><mspace width=\"1.0em\"></mspace><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> Fermi–Dirac (elektroi-gasa, Pauli)</mtext></mrow><mi>.</mi></mrow></math>"
