     "html": "CAx koaderno horiaren 6.-7. orri bikoitza: bost ariketa. Barne-erreferentzia bat dago: 6. orriak <math display=\"inline\"><mrow><mo stretchy=\"false\" form=\"prefix\">(</mo><mi>✱</mi><mo stretchy=\"false\" form=\"postfix\">)</mo></mrow></math>-z aipatzen du 7. orrian deduzitzen den <math display=\"inline\"><mrow><mi>f</mi><mo stretchy=\"false\" form=\"prefix\">(</mo><mi>r</mi><mo stretchy=\"false\" form=\"postfix\">)</mo></mrow></math> dentsitatea —orriak ez daude ordena logikoan—. Kanpo-iturri bat ere aipatzen da lehen aldiz lote osoan: <strong>SCHAUM 2.81</strong> formula-taula."
