     "html": "Batez besteko distantzia, <strong>SCHAUM 2.81</strong> taulako <math display=\"inline\"><mrow><mo>∫</mo><msup><mi>x</mi><mi>n</mi></msup><msup><mi>e</mi><mrow><mi>a</mi><mi>x</mi></mrow></msup><mi>d</mi><mi>x</mi></mrow></math> formularekin (<math display=\"inline\"><mrow><mi>n</mi><mo>=</mo><mn>3</mn></mrow></math>, <math display=\"inline\"><mrow><mi>a</mi><mo>=</mo><mi>−</mi><mn>2</mn><mi>/</mi><msub><mi>a</mi><mn>0</mn></msub></mrow></math>; <math display=\"inline\"><mrow><msubsup><mo>∫</mo><mn>0</mn><mi>∞</mi></msubsup><msup><mi>r</mi><mn>3</mn></msup><msup><mi>e</mi><mrow><mi>−</mi><mn>2</mn><mi>r</mi><mi>/</mi><msub><mi>a</mi><mn>0</mn></msub></mrow></msup><mi>d</mi><mi>r</mi><mo>=</mo><mn>3</mn><mi>!</mi><mi>/</mi><msup><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>2</mn><mi>/</mi><msub><mi>a</mi><mn>0</mn></msub><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mn>4</mn></msup><mo>=</mo><mn>3</mn><msubsup><mi>a</mi><mn>0</mn><mn>4</mn></msubsup><mi>/</mi><mn>8</mn></mrow></math>):"
