     "html": "Moda kalkulatzeko, <math display=\"inline\"><mrow><mi>f</mi><mo stretchy=\"false\" form=\"prefix\">(</mo><mi>r</mi><mo stretchy=\"false\" form=\"postfix\">)</mo><mo>=</mo><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>4</mn><mi>/</mi><msubsup><mi>a</mi><mn>0</mn><mn>3</mn></msubsup><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><msup><mi>r</mi><mn>2</mn></msup><msup><mi>e</mi><mrow><mi>−</mi><mn>2</mn><mi>r</mi><mi>/</mi><msub><mi>a</mi><mn>0</mn></msub></mrow></msup></mrow></math> deribatuz: <math display=\"block\"><mrow><msup><mi>f</mi><mo>′</mo></msup><mo stretchy=\"false\" form=\"prefix\">(</mo><mi>r</mi><mo stretchy=\"false\" form=\"postfix\">)</mo><mo>=</mo><mfrac><mn>8</mn><msubsup><mi>a</mi><mn>0</mn><mn>3</mn></msubsup></mfrac><mi>r</mi><msup><mi>e</mi><mrow><mi>−</mi><mn>2</mn><mi>r</mi><mi>/</mi><msub><mi>a</mi><mn>0</mn></msub></mrow></msup><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>1</mn><mo>−</mo><mfrac><mi>r</mi><msub><mi>a</mi><mn>0</mn></msub></mfrac><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>,</mo></mrow></math> zeinaren puntu kritikoak <math display=\"inline\"><mrow><mi>r</mi><mo>=</mo><mn>0</mn></mrow></math> (minimoa) eta <math display=\"inline\"><mrow><mi>r</mi><mo>=</mo><msub><mi>a</mi><mn>0</mn></msub></mrow></math> (maximo globala) diren. Beraz <strong>moda</strong> <math display=\"inline\"><mrow><mi>r</mi><mo>=</mo><msub><mi>a</mi><mn>0</mn></msub></mrow></math> da (Bohr-en erradioa), <math display=\"inline\"><mrow><mi>f</mi><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><msub><mi>a</mi><mn>0</mn></msub><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>=</mo><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>4</mn><mi>/</mi><msub><mi>a</mi><mn>0</mn></msub><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><msup><mi>e</mi><mrow><mi>−</mi><mn>2</mn></mrow></msup></mrow></math> balioarekin."
