        "<strong>Irudiak:</strong> barra-grafikoa (eskuizkribuan marraztua, berreginda) eta <math display=\"inline\"><mrow><mi>f</mi><mo stretchy=\"false\" form=\"prefix\">(</mo><mi>r</mi><mo stretchy=\"false\" form=\"postfix\">)</mo></mrow></math> dentsitate erradiala (editoreak gehitua, moda/batez bestekoa alderatzeko).",
