        "<strong>Berregiaztatua (Python):</strong> hamalau emaitzak zuzenak. Hidrogenoa: <math display=\"inline\"><mrow><mo>∫</mo><msup><mi>r</mi><mi>n</mi></msup><msup><mi>e</mi><mrow><mi>−</mi><mn>2</mn><mi>r</mi><mi>/</mi><msub><mi>a</mi><mn>0</mn></msub></mrow></msup></mrow></math> balioak (<math display=\"inline\"><mrow><mn>3</mn><msubsup><mi>a</mi><mn>0</mn><mn>5</mn></msubsup><mi>/</mi><mn>4</mn></mrow></math>, <math display=\"inline\"><mrow><mn>3</mn><msubsup><mi>a</mi><mn>0</mn><mn>4</mn></msubsup><mi>/</mi><mn>8</mn></mrow></math>, <math display=\"inline\"><mrow><msubsup><mi>a</mi><mn>0</mn><mn>3</mn></msubsup><mi>/</mi><mn>4</mn></mrow></math>), <math display=\"inline\"><mrow><mi>V</mi><mo stretchy=\"false\" form=\"prefix\">[</mo><mi>R</mi><mo stretchy=\"false\" form=\"postfix\">]</mo><mo>=</mo><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>3</mn><mi>/</mi><mn>4</mn><mo stretchy=\"false\" form=\"postfix\">)</mo><msubsup><mi>a</mi><mn>0</mn><mn>2</mn></msubsup></mrow></math>, <math display=\"inline\"><mrow><mi>σ</mi><mo>=</mo><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><msqrt><mn>3</mn></msqrt><mi>/</mi><mn>2</mn><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><msub><mi>a</mi><mn>0</mn></msub><mo>≈</mo></mrow></math> 0,866 <math display=\"inline\"><msub><mi>a</mi><mn>0</mn></msub></math>. Dado okertua: <math display=\"inline\"><mrow><mi>p</mi><mo>=</mo><mn>2</mn><mi>/</mi><mn>13</mn></mrow></math>, <math display=\"inline\"><mrow><mi>E</mi><mo stretchy=\"false\" form=\"prefix\">[</mo><mi>X</mi><mo stretchy=\"false\" form=\"postfix\">]</mo><mo>=</mo><mn>53</mn><mi>/</mi><mn>13</mn></mrow></math>, <math display=\"inline\"><mrow><mi>E</mi><mrow><mo stretchy=\"true\" form=\"prefix\">[</mo><msup><mi>X</mi><mn>2</mn></msup><mo stretchy=\"true\" form=\"postfix\">]</mo></mrow><mo>=</mo><mn>253</mn><mi>/</mi><mn>13</mn></mrow></math>, <math display=\"inline\"><mrow><mi>V</mi><mo stretchy=\"false\" form=\"prefix\">[</mo><mi>X</mi><mo stretchy=\"false\" form=\"postfix\">]</mo><mo>=</mo><mn>480</mn><mi>/</mi><mn>169</mn></mrow></math> <strong>bi bidetatik</strong> (definizioz eta <math display=\"inline\"><mrow><mi>E</mi><mrow><mo stretchy=\"true\" form=\"prefix\">[</mo><msup><mi>X</mi><mn>2</mn></msup><mo stretchy=\"true\" form=\"postfix\">]</mo></mrow><mo>−</mo><msup><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mi>E</mi><mo stretchy=\"false\" form=\"prefix\">[</mo><mi>X</mi><mo stretchy=\"false\" form=\"postfix\">]</mo><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mn>2</mn></msup></mrow></math>-z). Binomiala: <math display=\"inline\"><mrow><mtext mathvariant=\"normal\">Pr</mtext><mo stretchy=\"false\" form=\"prefix\">(</mo><mi>X</mi><mo>=</mo><mn>3</mn><mo stretchy=\"false\" form=\"postfix\">)</mo><mo>=</mo><mn>125</mn><mi>/</mi><mn>3888</mn><mo>≈</mo></mrow></math> 0,032; <math display=\"inline\"><mrow><mtext mathvariant=\"normal\">Bin</mtext><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>3</mn><mo>,</mo><mn>1</mn><mi>/</mi><mn>2</mn><mo stretchy=\"false\" form=\"postfix\">)</mo><mo>=</mo><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>1</mn><mi>/</mi><mn>8</mn><mo>,</mo><mn>3</mn><mi>/</mi><mn>8</mn><mo>,</mo><mn>3</mn><mi>/</mi><mn>8</mn><mo>,</mo><mn>1</mn><mi>/</mi><mn>8</mn><mo stretchy=\"false\" form=\"postfix\">)</mo></mrow></math> errekurrentziaz, batura <math display=\"inline\"><mn>1</mn></math>. (Ez dago EDF corpusean; Python-ez egiaztatua.)",
        "<strong>Zuzenketarik ez:</strong> hamalau emaitzak zuzenak. Bosgarren CAx unitatea jarraian zuzenketarik gabe. Autoreak bariantza <strong>bi bidetatik</strong> egiaztatzen du, kontrol egokia.",
        "<strong>Ez da ukitu (zalantza):</strong> 8. orrian, integral tabulatuaren ondoan, <math display=\"inline\"><mrow><mi>n</mi><mo>=</mo><mi>−</mi><mn>2</mn><mi>/</mi><msub><mi>a</mi><mn>0</mn></msub></mrow></math> irakur daiteke, baina <math display=\"inline\"><mrow><mi>−</mi><mn>2</mn><mi>/</mi><msub><mi>a</mi><mn>0</mn></msub></mrow></math> balioa esponentearen <math display=\"inline\"><mi>a</mi></math> parametroa da (<math display=\"inline\"><mi>n</mi></math> berretzailearen ordena da); etiketa-lapsus bat da, aurrerago ondo ordezkatzen duena.",
        "<strong>Irudia (editoreak gehitua):</strong> <math display=\"inline\"><mrow><mtext mathvariant=\"normal\">Bin</mtext><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>3</mn><mo>,</mo><mn>1</mn><mi>/</mi><mn>2</mn><mo stretchy=\"false\" form=\"postfix\">)</mo></mrow></math> barra-grafikoa, errekurrentziaren emaitza simetrikoa irudikatzeko; eskuizkribuak ez du marrazkirik (marjinako gurutze gorria bigarren problemaren hasiera-marka baino ez da).",
