        "<strong>Nabarmentzekoa:</strong> azken ariketan bariantza <math display=\"inline\"><mrow><mn>1</mn><mo>,</mo><msup><mn>8</mn><mn>2</mn></msup><mo>+</mo><mspace width=\"0.222em\"></mspace><mn>2</mn><mo>,</mo><msup><mn>6</mn><mn>2</mn></msup><mo>=</mo><mn>10</mn></mrow></math> <strong>zehazki</strong> da; datuak horretarako aukeratuta daude. Bi hurbilketetan (binomial eta Poisson) jarraitutasun-zuzenketa ondo aplikatzen da.",
